using Nini.Ini;
using System;using System.IO;using System.Text;using System.Collections.Generic;
class Program{
static byte[] Bytes(string s)=>s=="."?Array.Empty<byte>():Convert.FromHexString(s);static string HexBytes(byte[] b)=>b.Length==0?".":Convert.ToHexString(b).ToLowerInvariant();static string Dec(string s){if(s=="-")return null;var b=Bytes(s);var c=new char[b.Length/2];for(int i=0;i<c.Length;i++)c[i]=(char)(b[i*2]|(b[i*2+1]<<8));return new string(c);}static string Hex(string t){var b=new byte[t.Length*2];for(int i=0;i<t.Length;i++){b[i*2]=(byte)t[i];b[i*2+1]=(byte)(t[i]>>8);}return HexBytes(b);}static string Error(Exception e)=>e.GetType().FullName+":"+unchecked((uint)e.HResult)+":"+Hex(e.Message)+":"+((e as ArgumentException)?.ParamName is string p?Hex(p):"-")+(e is EncoderFallbackException f?":"+f.Index+":"+(int)f.CharUnknown:"")+(e is FileNotFoundException fn?":FN:"+(fn.FileName==null?"-":Hex(fn.FileName)):"")+(e is ObjectDisposedException od?":ON:"+Hex(od.ObjectName):"");
class S:Stream{public int chunk,point,nth,hit;public bool seek,readable,writable,closed;public long pos;public List<byte>data=new();public List<string>trace=new();void Event(int p,string text){trace.Add(text);if(point==p&&++hit==nth)throw new Exception("fault");}public override bool CanRead{get{Event(5,"CR");return readable&&!closed;}}public override bool CanWrite{get{Event(6,"CW");return writable&&!closed;}}public override bool CanSeek{get{Event(7,"CS");return seek&&!closed;}}public override long Position{get{Event(8,"G");return pos;}set{pos=value;}}public override long Length=>data.Count;public override int Read(byte[]b,int offset,int count){Event(1,"R:"+offset+":"+count);int n=(int)Math.Min(Math.Min(count,chunk),Math.Max(0,data.Count-pos));for(int i=0;i<n;i++)b[offset+i]=data[(int)pos+i];pos+=n;return n;}public override void Write(ReadOnlySpan<byte>b){Event(2,"W:"+HexBytes(b.ToArray()));int n=b.Length;bool partial=point==9&&++hit==nth;if(partial)n/=2;while(data.Count<pos+n)data.Add(0);for(int i=0;i<n;i++)data[(int)pos+i]=b[i];pos+=n;if(partial)throw new Exception("partial");}public override void Write(byte[] b,int o,int n)=>Write(b.AsSpan(o,n));public override void Flush()=>Event(3,"F");public override void Close(){Event(4,"C");closed=true;}public override long Seek(long o,SeekOrigin s)=>throw new NotSupportedException();public override void SetLength(long n)=>throw new NotSupportedException();}
static string Run(string row){var a=row.Split(' ');int kind=int.Parse(a[0]),flags=int.Parse(a[5]);var s=new S{chunk=int.Parse(a[2]),point=int.Parse(a[3]),nth=int.Parse(a[4]),seek=(flags&1)!=0,readable=(flags&2)!=0,writable=(flags&4)!=0,pos=long.Parse(a[6]),data=new List<byte>(Bytes(a[1]))};StreamReader reader=null;StreamWriter writer=null;string Snapshot()=>s.pos+":"+(s.closed?"1":"0")+":"+HexBytes(s.data.ToArray())+":"+(reader==null?"-":reader.CurrentEncoding.CodePage.ToString());var output=new List<string>();try{if(kind==0)reader=new StreamReader(s);else writer=new StreamWriter(s);}catch(Exception e){output.Add("CTOR:"+Error(e)+"/"+Snapshot());}if(output.Count==0)foreach(var token in a[7].Split(',')){var op=token.Split(':');string r=op[0];try{switch(op[0]){case "p":r="P:"+reader.Peek();break;case "r":r="R:"+reader.Read();break;case "all":var text=new StringBuilder();int c;while((c=reader.Read())!=-1)text.Append((char)c);r="A:"+Hex(text.ToString());break;case "w":writer.Write(Dec(op[1]));break;case "f":writer.Flush();break;case "c":if(reader!=null)reader.Close();else writer.Close();break;case "t":r="T:"+Hex(writer.ToString());break;case "pos":s.pos=long.Parse(op[1]);break;case "append":s.data.AddRange(Bytes(op[1]));break;default:throw new Exception("operation");}}catch(Exception e){r="EX:"+Error(e);}output.Add(r+"/"+Snapshot());}GC.SuppressFinalize(s);return string.Join("|",output)+"/IO:"+string.Join(";",s.trace);}
static string FileRun(string row){var args=row.Split(' ');int kind=int.Parse(args[0]);string path=Dec(args[1]);FileStream stream=null;StreamReader reader=null;StreamWriter writer=null;var held=new List<FileStream>();var output=new List<string>();string State(){try{return stream==null?"-":stream.Position.ToString();}catch(Exception){return "unavailable";}}
try{if(kind==0){stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read,4096);reader=new StreamReader(stream);}else if(kind==1){stream=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None,4096);writer=new StreamWriter(stream);}else if(kind==2){stream=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.Read,4096);writer=new StreamWriter(stream);}}catch(Exception e){output.Add("CTOR:"+Error(e));}
if(output.Count==0)foreach(var token in args[2].Split(',')){var a=token.Split(':');string r=a[0];try{switch(a[0]){case "w":writer.Write(Dec(a[1]));break;case "f":writer.Flush();break;case "c":if(reader!=null)reader.Close();else writer.Close();break;case "p":r="P:"+reader.Peek();break;case "r":r="R:"+reader.Read();break;case "all":var text=new StringBuilder();int c;while((c=reader.Read())!=-1)text.Append((char)c);r="A:"+Hex(text.ToString());break;case "openr":held.Add(new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read,4096));break;case "openw":held.Add(new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.Read,4096));break;case "inspect":using(var inspect=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite,4096)){using var memory=new MemoryStream();inspect.CopyTo(memory);r="B:"+HexBytes(memory.ToArray());}break;case "raw":stream.Write(Bytes(a[1]));break;case "sf":stream.Flush();break;case "sc":stream.Close();break;case "t":r="T:"+Hex(writer.ToString());break;default:throw new Exception("fileop");}}catch(Exception e){r="EX:"+Error(e);}output.Add(r+"/"+State());}
try{writer?.Close();}catch(Exception){}try{reader?.Close();}catch(Exception){}foreach(var h in held)h.Close();return string.Join("|",output);}
static string IniFile(string row){var a=row.Split(' ');int kind=int.Parse(a[0]),ft=int.Parse(a[2]);string path=Dec(a[1]),value=Dec(a[3]);try{if(kind==0){var w=new IniWriter(path);w.WriteSection("配置😀");w.WriteKey("key",value,"comment");w.Close();GC.SuppressFinalize(w);return "OK:"+(int)w.WriteState;}if(kind==1){var d=new IniDocument();d.FileType=(IniFileType)ft;var section=new IniSection("配置😀","section comment");section.Set("key",value,"comment");section.Set("empty comment");d.Sections.Add(section);d.Save(path);return "OK";}var doc=new IniDocument(path,(IniFileType)ft);var output=new StringWriter();doc.Save(output);return "TEXT:"+Hex(output.ToString());}catch(Exception e){return "EX:"+Error(e);}}
static void Main(string[] args){if(args.Length>0&&args[0]=="--runtime"){Console.WriteLine(Environment.Version);Console.WriteLine(typeof(StreamReader).Assembly.Location);return;}System.Globalization.CultureInfo.CurrentCulture=System.Globalization.CultureInfo.InvariantCulture;System.Globalization.CultureInfo.CurrentUICulture=System.Globalization.CultureInfo.InvariantCulture;string row;while((row=Console.ReadLine())!=null){Console.WriteLine(args.Length>0&&args[0]=="--ini-file-probe"?IniFile(row):args.Length>0&&args[0]=="--file-probe"?FileRun(row):Run(row));if(args.Length>0&&args[0]=="--ini-file-probe"){GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();}}}
